"""label_provenance on invented data only (no real data; MIMIC function on synthetic rows)."""

import pandas as pd
import pytest

from stemi.review import label_provenance as lp


def _db():
    return pd.DataFrame({
        "ecg_id": [1, 2, 3, 4], "patient_id": [10, 10, 11, 12],
        "scp_codes": ["{'IMI': 100.0}", "{'IMI': 50.0, 'STE_': 0.0}", "{'NORM': 100.0}", "{'IMI': 100.0}"],
        "validated_by_human": ["True", "False", "True", "True"],
        "second_opinion": ["False", "True", "False", "False"],
        "initial_autogenerated_report": ["False", "True", "True", "False"],
        "validated_by": ["1.0", None, "0.0", None],
    })


def test_ptbxl_counts():
    out = lp.ptbxl_provenance(_db(), ["IMI", "STE_", "PMI"]).set_index("code")
    r = out.loc["IMI"]
    assert (r.n_ecgs, r.n_patients) == (3, 2)
    assert (r.validated_by_human_true, r.validated_by_human_false) == (2, 1)
    assert (r.second_opinion_true, r.initial_autogenerated_report_true) == (1, 1)
    assert r.autogenerated_and_not_validated_by_human == 1 and r.validated_by_filled == 1
    assert r.n_ecgs_likelihood_100 == 2
    assert out.loc["STE_", "n_ecgs"] == 1 and out.loc["PMI", "n_ecgs"] == 0


def test_missing_provenance_column_is_reported():
    with pytest.raises(KeyError, match="second_opinion"):
        lp.ptbxl_provenance(_db().drop(columns="second_opinion"), ["IMI"])


def test_scope_includes_mi_st_isc_and_crosswalk_codes():
    s = set(lp.ptbxl_scope())
    assert {"IMI", "INJAS", "STE_", "STD_", "NST_", "ISCAN", "NORM", "SR", "TAB_", "LNGQT"} <= s


def test_code15_no_origin_column():
    df = pd.DataFrame({"exam_id": [1], "AF": [True], "ST": [False], "trace_file": ["x"]})
    out = lp.code15_columns(df).set_index("column")
    assert out.loc["AF", "is_label_column"] and not out.loc["trace_file", "is_label_column"]
    assert not out["origin_column_found"].any()


def test_mimic_groups_suppression_and_no_ids():
    rows = [{"ecg": f"e{i}", "pt": f"p{i}", "codes": "['I2101', 'I10']", "src": "hosp"} for i in range(12)]
    rows += [{"ecg": "x1", "pt": "q1", "codes": "I21.4;I252", "src": "ed"}]
    out = lp.mimic_icd_group_counts(pd.DataFrame(rows), ecg_col="ecg", patient_col="pt",
                                    code_col="codes", source_col="src")
    allrows = out[out["diagnosis_source"] == "all"].set_index("icd_group")
    assert allrows.loc["I21.0-I21.3", "ecgs"] == "12"
    assert allrows.loc["I21.4", "ecgs"] == "<10" and allrows.loc["I25.2", "patients"] == "<10"
    assert set(out["diagnosis_source"]) == {"all", "ed", "hosp"}
    text = out.to_csv()
    assert "e1" not in text and "p1" not in text and "x1" not in text


def test_codes_in_cell_formats():
    assert lp._codes_in_cell("['I21.4', 'i10']") == ["I214", "I10"]
    assert lp._codes_in_cell("I2101") == ["I2101"]
    assert lp._codes_in_cell(None) == []
